class Solution {
public:
    int minSizeSubarray(vector<int>& nums, int target) {
        long long S = 0;
        for (int x : nums) S += x;
        int n = nums.size();
        long long q = target / S;
        long long r = target % S;
        if (r == 0) return (int)(q * n);
        int best = INT_MAX;
        long long cur = 0;
        int j = 0;
        for (int i = 0; i < 2 * n; i++) {
            cur += nums[i % n];
            while (cur > r) {
                cur -= nums[j % n];
                j++;
            }
            if (cur == r) best = min(best, i - j + 1);
        }
        if (best == INT_MAX) return -1;
        return (int)(q * n + best);
    }
};
